<?php if($admin): $attempt=$db->one('SELECT * FROM byp_shop_payments WHERE order_id=?',[$order['id']]);if($attempt): ?><section class="c-card"><h2>Платёж</h2><p>Состояние: <?= $e($attempt['state']) ?> · Режим: <?= $e($attempt['mode']) ?></p><p>Операция: <?= $e($attempt['operation']) ?><br>ID ЮKassa: <?= $e($attempt['provider_id']?:'Ответ ещё не получен') ?></p><p><?= $e($attempt['last_error']) ?></p><?php if($order['state']==='pending'): ?><form method="post"><?php $form('payment_recover',['id'=>$order['id']]); ?><label>ID платежа из кабинета ЮKassa<input name="provider_id" value="<?= $e($attempt['provider_id']??'') ?>" required></label><button>Сверить с провайдером</button></form><p>Вручную отметить заказ оплаченным нельзя. Сверка проверяет магазин, режим, сумму, валюту и номер заказа.</p><?php endif ?></section><?php endif;endif ?><?php if($admin): ?><section class="c-card"><h2>Возвраты</h2><p>Покупатель отправляет запрос; возврат запускает администратор после рассмотрения. Остатки не увеличиваются автоматически при возврате денег.</p><p>Подтверждено: <?= Shop::money((int)$order['refunded']) ?></p><?php foreach($refunds as $r): ?><p>#<?= $r['id'] ?> · <?= Shop::money((int)$r['amount']) ?> · <?= $e($r['state'].' '.$r['last_error']) ?></p><?php if($r['state']==='pending'): ?><form method="post"><?php $form('refund',['id'=>$order['id'],'amount'=>PaymentGateway::amount((int)$r['amount']),'operation'=>$r['operation']]); ?><button>Проверить / повторить эту операцию</button></form><?php endif;endforeach;if($order['state']==='paid'&&!array_filter($refunds,fn($r)=>$r['state']==='pending')): ?><form method="post" data-confirm="Подтвердить возврат указанной суммы через ЮKassa?"><?php $form('refund',['id'=>$order['id'],'operation'=>$_POST['operation']??Shop::uuid()]); ?><?php $original=$attempt?json_decode($attempt['body'],true):[];if(isset($original['receipt'])): $used=[];foreach($refunds as $previous)if($previous['state']!=='canceled')foreach((json_decode($previous['body'],true)['selection']??[])as $index=>$qty)$used[$index]=($used[$index]??0)+(int)$qty;foreach($original['receipt']['items']as $index=>$line): $available=(int)$line['quantity']-($used[$index]??0); ?><label><?= $e($line['description']) ?> · <?= $e($line['amount']['value']) ?> ₽/шт. · осталось <?= $available ?><input type="number" name="return_items[<?= $index ?>]" value="0" min="0" max="<?= $available ?>"></label><?php endforeach ?><p>Сумма рассчитывается по выбранным позициям исходного чека с учётом скидки. Доставка возвращается только при её явном выборе.</p><?php else: ?><label>Сумма, ₽<input name="amount" inputmode="decimal" placeholder="100.00" required value="<?= $e($_POST['amount']??'') ?>"></label><?php endif ?><button>Вернуть указанную сумму</button></form><?php endif;if($order['state']==='refunded'&&!$order['stock_released']): ?><form method="post"><?php $form('restock',['id'=>$order['id']]); ?><label class="c-check"><input type="checkbox" name="confirm" required> Все товары фактически получены обратно и доступны для продажи</label><button>Вернуть товары в остатки</button></form><?php endif ?></section><?php endif;}
elseif($section==='groups'): $group=null;foreach($shop->groups()as $row)if((int)$row['id']===(int)($_GET['group']??0))$group=$row;$values=$error?$_POST:($group??['id'=>0,'kind'=>'collection','title'=>'','description'=>'','image'=>'']); ?><h1>Подборки, категории и бренды</h1><p>Название связывает подборку с товарами. При переименовании связи обновляются. Пустая подборка остаётся доступной по своей ссылке.</p><section class="c-card"><form method="post"><?php $form('group',['id'=>$values['id']??0]); ?><label>Тип<select name="kind"><?php foreach(['category'=>'Категория','collection'=>'Коллекция','brand'=>'Бренд']as $key=>$label): ?><option value="<?= $key ?>" <?= ($values['kind']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label>Название<input name="title" value="<?= $e($values['title']??'') ?>" maxlength="120" required></label><label>Описание<textarea name="description" rows="4"><?= $e($values['description']??'') ?></textarea></label><label>Изображение<input name="cover" value="<?= $e($values['cover']??$values['image']??'') ?>"></label><button type="button" data-shop-media>Выбрать / загрузить фото</button><button>Сохранить подборку</button></form></section><?php foreach($shop->groups()as $row): ?><section class="c-card"><h2><?= $e($row['title']) ?></h2><p><?= $e($row['kind']) ?></p><a href="<?= $back ?>&group=<?= $row['id'] ?>">Редактировать →</a> · <a href="/catalog/?<?= $e(http_build_query([$row['kind']=>$row['title']])) ?>" target="_blank" rel="noopener">Открыть ↗</a></section><?php endforeach ?><?php
elseif($section==='connections'): $values=$error?array_merge($settings,$_POST):$settings; ?><h1>Настройки магазина</h1><p>Оплата и SMTP — независимые подключения. Заказ сохраняется даже при недоступном провайдере или почте. Письма отправляются через CLI worker, ошибки видны в журнале.</p><form method="post"><?php $form('configure'); ?><section class="c-card"><h2>ЮKassa</h2><label class="c-check"><input type="checkbox" name="enabled" <?= !empty($values['enabled'])?'checked':'' ?>> Включить онлайн-оплату</label><label>Режим<select name="mode"><option value="test">Тестовый</option><option value="live" <?= $values['mode']==='live'?'selected':'' ?>>Боевой</option></select></label><label>Shop ID<input name="shop_id" value="<?= $e($values['shop_id']) ?>"></label><label>Секретный ключ <?= $settings['shop_secret_saved']?'(сохранён)':'' ?><input type="password" name="shop_secret" autocomplete="new-password" value=""></label><label class="c-check"><input type="checkbox" name="clear_shop_secret"> Удалить сохранённый ключ</label><p>В кабинете ЮKassa: уведомления payment.succeeded, payment.canceled и refund.succeeded → <?= $e(rtrim($config['app']['url'],'/')) ?>/payment-notification/</p><label class="c-check"><input type="checkbox" name="receipt_enabled" <?= !empty($values['receipt_enabled'])?'checked':'' ?>> Передавать состав чека (при подключённой фискализации)</label><label>Код системы налогообложения (0 — из кабинета)<input type="number" min="0" max="6" name="tax_system" value="<?= (int)$values['tax_system'] ?>"></label><label>Код НДС ЮKassa<input type="number" min="1" max="12" name="vat_code" value="<?= (int)$values['vat_code'] ?>"></label></section><section class="c-card"><h2>Получение и промокод</h2><label>Стоимость доставки, копейки<input type="number" name="shipping_cost" min="0" value="<?= (int)$values['shipping_cost'] ?>"></label><label>Адрес самовывоза (пусто — выключен)<input name="pickup_address" value="<?= $e($values['pickup_address']) ?>"></label><label>Активный промокод<input name="promo_code" value="<?= $e($values['promo_code']) ?>"></label><label>Скидка, %<input name="promo_percent" type="number" min="0" max="90" value="<?= (int)$values['promo_percent'] ?>"></label></section><section class="c-card"><h2>Почтовые уведомления</h2><label class="c-check"><input type="checkbox" name="smtp_enabled" <?= !empty($values['smtp_enabled'])?'checked':'' ?>> Включить отправку SMTP</label><?php foreach(['smtp_host'=>'SMTP host','smtp_user'=>'Логин','from_email'=>'Email отправителя','from_name'=>'Имя отправителя']as $k=>$label): ?><label><?= $label ?><input name="<?= $k ?>" value="<?= $e($values[$k]) ?>"></label><?php endforeach ?><label>Защита<select name="smtp_security"><option value="starttls">STARTTLS / 587</option><option value="ssl" <?= $values['smtp_security']==='ssl'?'selected':'' ?>>SSL / 465</option></select></label><label>Порт<input name="smtp_port" type="number" value="<?= (int)$values['smtp_port'] ?>"></label><label>Пароль SMTP <?= $settings['smtp_password_saved']?'(сохранён)':'' ?><input name="smtp_password" type="password" autocomplete="new-password" value=""></label><label class="c-check"><input type="checkbox" name="clear_smtp_password"> Удалить сохранённый пароль</label><p>Настройте cron (раз в минуту): php /путь/к/сайту/_core/shop-worker.php. Логи не содержат пароль.</p></section><button class="c-primary">Сохранить настройки</button></form>
<?php elseif($section==='shop-mail'): ?><h1>Журнал писем</h1><p>accepted — сервер SMTP принял письмо, это не гарантия доставки во входящие. При uncertain перед повтором проверьте почту: возможен дубль.</p><?php foreach($db->all('SELECT m.*,o.reference FROM byp_shop_mail m JOIN byp_shop_orders o ON o.id=m.order_id ORDER BY m.id DESC LIMIT 100')as $m): ?><section class="c-card"><h2><?= $e($m['reference']) ?></h2><p><?= $e($m['event_key'].' / '.$m['state']) ?> · Попыток: <?= (int)$m['attempts'] ?></p><p><?= $e($m['last_error']) ?></p><?php if($m['state']!=='accepted'): ?><form method="post"><?php $form('mail',['id'=>$m['id']]);if(in_array($m['state'],['uncertain','sending'],true)): ?><label class="c-check"><input type="checkbox" name="acknowledge" required> Проверил почту и допускаю повторную доставку</label><?php endif ?><button>Отправить / повторить</button></form><?php endif ?></section><?php endforeach;endif ?>
</main></div><dialog id="shop-media"><div class="c-heading"><h2>Выберите изображение</h2><button type="button" data-shop-close>Закрыть ×</button></div><label>Загрузить фото<input type="file" id="shop-upload" accept="image/jpeg,image/png,image/webp,image/gif"></label><label>Поиск<input type="search" id="shop-media-query" placeholder="Имя или alt-текст"></label><button type="button" id="shop-media-find">Найти</button><p id="shop-media-status" role="status"></p><div id="shop-media-grid"></div><button type="button" id="shop-media-prev">Назад</button><span id="shop-media-page"></span><button type="button" id="shop-media-next">Далее</button></dialog></body></html>
